INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000001, 2230000000000000001, 1, 'Spring Boot 自动配置到底是怎么生效的', '从 @SpringBootApplication 拆到 AutoConfigurationImportSelector，再追到 spring.factories 与 AutoConfiguration.imports，把「引入依赖就能用」这件事讲透。', 'https://img.sdblog.us.ci/ruoyi/2026/09/30/1244374ebda34594ab6a220298f8c617.jpg', '<h2>一个让人困惑的现象</h2><p>加上 <code>spring-boot-starter-web</code> 依赖，什么都没配，Tomcat 就起来了、Jackson 就注册好了。这套「约定优于配置」的魔法入口，其实只有三个环节。</p><h2>第一环：@SpringBootApplication 是三个注解的合成</h2><p>它等价于 <code>@SpringBootConfiguration</code>、<code>@EnableAutoConfiguration</code>、<code>@ComponentScan</code>。真正干活的是中间那个。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/09/30/1244374ebda34594ab6a220298f8c617.jpg" alt="Spring Boot 自动配置到底是怎么生效的 · 示意图一" loading="lazy"><figcaption>Spring Boot 自动配置到底是怎么生效的 · 示意图一</figcaption></figure><pre><code class="language-java"><span class="tok-140thh">@</span><span class="tok-1itgoe">SpringBootApplication</span>
