INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000003, 2230000000000000003, 1, 'Redis 缓存穿透、击穿、雪崩：三种病与三张药方', '名字很像，成因完全不同。把三者拆开讲清楚，再分别给布隆过滤器、互斥锁、过期时间打散的具体做法。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/a0d7253288d34e9492f52f9e88863b55.jpg', '<h2>三种故障的差别</h2><ul><li><strong>穿透</strong>：查一个数据库里也不存在的 key，缓存永远不命中</li><li><strong>击穿</strong>：某个热点 key 恰好过期，瞬间请求全打到数据库</li><li><strong>雪崩</strong>：大批 key 同一时刻过期，或 Redis 整体不可用</li></ul><h2>穿透：先挡掉不可能的请求</h2><p>布隆过滤器能判断「这个 key 一定不存在」，把无效请求挡在缓存层之前。代价是存在极小的误判率，且不支持删除。</p><pre><code class="language-java"><span class="tok-1itgoe">if</span><span class="tok-140thh"> (</span><span class="tok-1itgoe">!</span><span class="tok-140thh">bloomFilter.</span><span class="tok-1t8gfj">mightContain</span><span class="tok-140thh">(key)) {</span>
