INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000004, 2230000000000000004, 1, 'Vue 3 响应式系统拆解：Proxy 与依赖收集', '从 reactive() 到 effect()，把 track 与 trigger 两个过程走一遍，解释为什么 Vue 3 能精确到属性级别触发更新。', 'https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg', '<h2>Vue 2 的 Object.defineProperty 撞到了什么墙</h2><p>它只能劫持已存在的属性：新增属性要 <code>$set</code>，数组方法要重写，深层对象要递归遍历。Vue 3 换成 Proxy 后，这三个问题一起消失。</p><pre><code class="language-javascript"><span class="tok-1itgoe">const</span><span class="tok-dzsirb"> state</span><span class="tok-1itgoe"> =</span><span class="tok-1t8gfj"> reactive</span><span class="tok-140thh">({ count: </span><span class="tok-dzsirb">0</span><span class="tok-140thh"> });</span>
