INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000007, 2230000000000000007, 1, '我把自己的博客下线了一天', '一次「主动下线」的复盘：为什么隐藏文章、隐藏和删除的区别、以及读者视角下应该看到什么。', 'https://img.sdblog.us.ci/ruoyi/2026/10/09/8e666e85dffe4c4dbe7b106c5170bfb6.jpg', '<h2>起因</h2><p>有篇文章里的示例代码在生产环境跑出了事故，虽然文章本身没错，但我不想在没补充警告前让它继续传播。</p><h2>隐藏不是删除</h2><p>隐藏后文章还在、版本还在、链接会 404 但数据完整；删除是逻辑删除，作者自己也看不到了。前者可逆，后者要找回很麻烦。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg" alt="我把自己的博客下线了一天 · 示意图一" loading="lazy"><figcaption>我把自己的博客下线了一天 · 示意图一</figcaption></figure><blockquote><p>内容平台的「下线」应该是可逆操作，且必须记录原因与操作人——这次我给自己补上了这条。</p></blockquote><h2>读者看到什么</h2><p>列表里消失，直达链接提示已下线。不显示「作者删除了」这类容易误解的文案。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="我把自己的博客下线了一天 · 示意图二" loading="lazy"><figcaption>我把自己的博客下线了一天 · 示意图二</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
