INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000009, 2230000000000000009, 1, 'JVM 内存模型与一次 OOM 排查实录', '堆、元空间、直接内存各管什么，以及线上一次 java.lang.OutOfMemoryError: Metaspace 的完整定位过程。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg', '<h2>三个容易混淆的区域</h2><ul><li>堆：对象实例，受 -Xmx 约束</li><li>元空间：类元数据，受 -XX:MaxMetaspaceSize 约束</li><li>直接内存：NIO / Netty 的堆外分配，受 -XX:MaxDirectMemorySize 约束</li></ul><h2>现场：Metaspace 缓慢上涨</h2><p>服务跑了三天后告警，GC 日志显示 Full GC 频繁但堆很空。用 <code>jcmd &lt;pid&gt; VM.metaspace</code> 看到类加载数量持续增长——是热部署的 ClassLoader 没释放。</p><pre><code class="language-bash"><span class="tok-1t8gfj">jcmd</span><span class="tok-140thh"> $PID </span><span class="tok-mdbnqw">VM.metaspace</span><span class="tok-mdbnqw"> summary</span>
