INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000010, 2230000000000000010, 1, 'Kafka 消息积压的排查路径', '从 consumer lag 出发，分清是消费慢、分区不均，还是消费者掉线。给一套五分钟内能定位顺序的检查表。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg', '<h2>先看 lag，再看分布</h2><p><code>kafka-consumer-groups --describe</code> 会列出每个分区的 lag。如果只有一个分区积压，是分区键设计问题；全部分区均匀积压，才是消费能力不足。</p><pre><code class="language-bash"><span class="tok-1t8gfj">kafka-consumer-groups.sh</span><span class="tok-dzsirb"> --bootstrap-server</span><span class="tok-mdbnqw"> localhost:9092</span><span class="tok-dzsirb"> \\</span>
