INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000012, 2230000000000000012, 1, '前端性能优化：从 Lighthouse 64 分到 95 分', '一次真实的调优记录。掉分的不是 JS，是三张未压缩的封面原图和 101 条 @font-face 声明。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg', '<h2>先看扣分项，别看总分</h2><p>Lighthouse 的 Performance 是加权分。打开 details 会看到 <code>total-byte-weight</code> 只有 50 分——3.8MB 的首屏字节几乎全是未裁剪的封面原图。</p><h2>三个动作</h2><ul><li>图片按展示尺寸取，不是按原图直出</li><li>字体子集化 + 按字符集分片，首屏只下用到的片</li><li>把渲染阻塞的 CSS 拆出关键部分</li></ul><h2>一个反直觉的事实</h2><p>减少 JS 体积对 DCL 有帮助，但对 LCP 往往没感觉——因为 LCP 元素通常是图片或标题文字，早已被更早的资源卡住。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="前端性能优化：从 Lighthouse 64 分到 95 分 · 示意图一" loading="lazy"><figcaption>前端性能优化：从 Lighthouse 64 分到 95 分 · 示意图一</figcaption></figure><blockquote><p>优化要先确定 LCP 元素是什么，再决定砍什么。否则容易优化了不影响分数的部分。</p></blockquote><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
