INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000013, 2230000000000000013, 1, 'CSS 布局演进：从 Float 到 Grid', '不是历史课。讲清楚每种方案当年解决什么、留下什么坑，以及为什么现在仍然会见到 float 清浮动。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/a0d7253288d34e9492f52f9e88863b55.jpg', '<h2>Float 本来是给文字环绕的</h2><p>用它做多列布局是历史误会，代价是要清浮动、要用 clearfix 这类补丁。</p><h2>Flex 解决一维分布</h2><pre><code class="language-css"><span class="tok-1t8gfj">.row</span><span class="tok-140thh"> {</span>
