INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000015, 2230000000000000015, 1, 'Git 分支模型：GitFlow、Trunk-Based 与团队规模', '5 人团队用 GitFlow 会累死，50 人用纯主干又容易互相踩。给出按团队规模选择的判断依据。', 'https://img.sdblog.us.ci/ruoyi/2026/10/08/c03f78e8acd9458894b03775ba998b5e.jpg', '<h2>GitFlow 的成本在哪</h2><p>五条长期分支意味着每次发版都要做合并、打 tag、再合回 develop。小团队没有人专职管发布，这套流程会迅速变成负担。</p><h2>Trunk-Based 的前提</h2><ul><li>有可靠的自动化测试</li><li>发布与部署解耦（开关 / 灰度）</li><li>提交粒度足够小</li></ul><blockquote><p>分支模型的本质是「并行开发度的管理」。约束在于合并成本，而不在于工具。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/08/c03f78e8acd9458894b03775ba998b5e.jpg" alt="Git 分支模型：GitFlow、Trunk-Based 与团队规模 · 示意图一" loading="lazy"><figcaption>Git 分支模型：GitFlow、Trunk-Based 与团队规模 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg" alt="Git 分支模型：GitFlow、Trunk-Based 与团队规模 · 示意图二" loading="lazy"><figcaption>Git 分支模型：GitFlow、Trunk-Based 与团队规模 · 示意图二</figcaption></figure><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
