INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000017, 2230000000000000017, 1, '单元测试的价值边界：什么该测、什么不该测', '不是覆盖率越高越好。区分「纯逻辑」与「接线代码」，把测试预算花在会出错的地方。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg', '<h2>值得测的</h2><ul><li>状态机转换与边界条件</li><li>解析、规范化、拼装这类纯函数</li><li>曾经出过 bug 的地方（回归测试）</li></ul><h2>不值得测的</h2><ul><li>getter / setter 与简单映射</li><li>框架已经保证的行为</li><li>为了覆盖率而写的断言空壳</li></ul><blockquote><p>测试的价值在于「改错时会红」。一条永远绿的测试，不如没有。</p></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg" alt="单元测试的价值边界：什么该测、什么不该测 · 示意图一" loading="lazy"><figcaption>单元测试的价值边界：什么该测、什么不该测 · 示意图一</figcaption></figure><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="单元测试的价值边界：什么该测、什么不该测 · 示意图二" loading="lazy"><figcaption>单元测试的价值边界：什么该测、什么不该测 · 示意图二</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
