INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000018, 2230000000000000018, 1, '代码评审清单：200 次 Review 总结的 12 条', '按「必须改 / 建议改 / 可以聊」三档归类，避免把个人偏好当成阻塞项。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg', '<h2>必须改</h2><ul><li>并发与事务边界是否正确</li><li>异常是否被吞掉</li><li>是否引入 N+1 查询</li><li>敏感信息是否落日志</li><li>是否有破坏性变更未标注</li></ul><h2>建议改</h2><ul><li>命名是否表意</li><li>是否有更简单的写法</li><li>重复逻辑能否提取</li></ul><h2>可以聊</h2><ul><li>风格偏好</li><li>更激进的架构调整</li></ul><blockquote><p>把个人偏好标成「必须改」是评审最常见的摩擦源。分档之后，讨论会顺畅很多。</p></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg" alt="代码评审清单：200 次 Review 总结的 12 条 · 示意图一" loading="lazy"><figcaption>代码评审清单：200 次 Review 总结的 12 条 · 示意图一</figcaption></figure><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
