INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000020, 2230000000000000020, 1, 'MySQL 事务隔离级别：幻读到底能不能避免', '四种隔离级别各自解决什么、MVCC 与间隙锁分别在哪一层起作用，以及为什么 RR 下仍会遇到幻读。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/b8000d2667af49a28ed193eee931986a.jpg', '<h2>四种级别与它们的问题</h2><ul><li>读未提交：脏读</li><li>读已提交：不可重复读</li><li>可重复读：理论上有幻读</li><li>串行化：性能代价</li></ul><h2>MVCC 让「读」不用加锁</h2><p>快照读走 undo log 版本链，所以 RR 下的普通 SELECT 能保持一致。</p><h2>幻读出现在当前读</h2><p><code>SELECT ... FOR UPDATE</code> 是当前读，必须加锁。InnoDB 用间隙锁把区间锁住来防插入——但如果查询没走索引，它会锁全表，代价极大。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="MySQL 事务隔离级别：幻读到底能不能避免 · 示意图一" loading="lazy"><figcaption>MySQL 事务隔离级别：幻读到底能不能避免 · 示意图一</figcaption></figure><blockquote><p>「RR 能防幻读」这句话只在快照读成立。当前读要靠间隙锁，而间隙锁的代价经常被低估。</p></blockquote><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
