INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000022, 2230000000000000022, 1, 'Elasticsearch 中文分词：词典与召回率', 'IK 的 ik_smart 与 ik_max_word 何时用哪个，技术术语词典怎么补，以及召回率低的三个排查方向。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg', '<h2>两个模式的区别</h2><p><code>ik_max_word</code> 切得细，索引时用；<code>ik_smart</code> 切得粗，搜索时用。反了会导致召回异常。</p><h2>技术术语必须加词典</h2><p>默认词典会把「微服务」切成「微」「服务」，把 Redis 当英文单词。自定义 <code>tech.dic</code> 后效果立竿见影。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="Elasticsearch 中文分词：词典与召回率 · 示意图一" loading="lazy"><figcaption>Elasticsearch 中文分词：词典与召回率 · 示意图一</figcaption></figure><blockquote><p>分词的调优目标不是「切得准」，是「搜得到」。先定召回，再谈精度。</p></blockquote><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
