INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000027, 2230000000000000027, 1, 'Redis 持久化：RDB 与 AOF 怎么选', '两种机制的数据安全边界不同。讲清 fork 开销、AOF 重写、以及混合持久化为什么成为默认推荐。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg', '<h2>RDB 是快照</h2><p>按时间点 fork 子进程写盘。恢复快，但两次快照之间的数据会丢。fork 时内存翻倍的风险在大实例上不能忽略。</p><h2>AOF 是日志</h2><p>逐条记录写命令，<code>appendfsync everysec</code> 最多丢一秒。代价是文件膨胀，需要重写。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg" alt="Redis 持久化：RDB 与 AOF 怎么选 · 示意图一" loading="lazy"><figcaption>Redis 持久化：RDB 与 AOF 怎么选 · 示意图一</figcaption></figure><h2>混合持久化</h2><p>Redis 4.0 起可开启 <code>aof-use-rdb-preamble</code>：重写时前半段是 RDB 快照、后半段是增量命令，兼顾恢复速度与数据安全。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="Redis 持久化：RDB 与 AOF 怎么选 · 示意图二" loading="lazy"><figcaption>Redis 持久化：RDB 与 AOF 怎么选 · 示意图二</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
