INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000030, 2230000000000000030, 1, 'RESTful API 设计中的五个常见错误', '动词进路径、状态码乱用、分页参数不一致、错误结构不统一、以及 GET 带副作用。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg', '<h2>动词进路径</h2><p><code>POST /articles/create</code> 不如 <code>POST /articles</code>。HTTP 方法本身就是动词。</p><h2>状态码</h2><ul><li>参数校验失败用 400，不要用 500</li><li>未登录 401，无权限 403，不要混</li><li>创建成功返回 201 并带 Location</li></ul><h2>错误结构统一</h2><pre><code class="language-json"><span class="tok-140thh">{ </span><span class="tok-dzsirb">"code"</span><span class="tok-140thh">: </span><span class="tok-dzsirb">40001</span><span class="tok-140thh">, </span><span class="tok-dzsirb">"msg"</span><span class="tok-140thh">: </span><span class="tok-mdbnqw">"标题不能为空"</span><span class="tok-140thh">, </span><span class="tok-dzsirb">"data"</span><span class="tok-140thh">: </span><span class="tok-dzsirb">null</span><span class="tok-140thh"> }</span></code></pre><blockquote><p>API 是给别人用的契约。一致比「更合理」重要。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="RESTful API 设计中的五个常见错误 · 示意图一" loading="lazy"><figcaption>RESTful API 设计中的五个常见错误 · 示意图一</figcaption></figure></blockquote><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
