INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000031, 2210000000000000001, NULL, '1', '0', 2240000000000000031, 4120, '2026-10-20 15:30:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000001, '2026-10-20 12:30:00', 2210000000000000001, '2026-10-20 12:30:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000031, 2230000000000000031, 1, '如何写好一份技术方案', '方案不是文档堆砌。讲清背景、目标与非目标、备选方案对比、风险与回滚，四段结构就够。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg', '<h2>四段结构</h2><ul><li>背景：现在有什么问题，为什么现在要做</li><li>目标与非目标：明确不做什么，避免范围蔓延</li><li>备选方案：至少两个，含否决理由</li><li>风险与回滚：出问题怎么退</li></ul><h2>最常被跳过的「非目标」</h2><p>不写非目标，评审时就会不断有人问「那 X 也一起做了吧」。写下不做，比写下做更难，也更重要。</p><blockquote><p>好方案的标准不是「写得全」，是「别人看完能判断该不该批」。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/09/30/1244374ebda34594ab6a220298f8c617.jpg" alt="如何写好一份技术方案 · 示意图一" loading="lazy"><figcaption>如何写好一份技术方案 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg" alt="如何写好一份技术方案 · 示意图二" loading="lazy"><figcaption>如何写好一份技术方案 · 示意图二</figcaption></figure><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p>', 1761000000000000103, 2210000000000000001, '2026-10-20 12:30:00', 2210000000000000001, '2026-10-20 12:30:00', '0');
