INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000032, 2230000000000000032, 1, 'Spring Security 与 Sa-Token 的取舍', '一个偏标准、一个偏易用。从学习曲线、扩展点、与现有权限模型的契合度三个维度对比。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg', '<h2>Spring Security 的强项</h2><p>标准化、生态完整、与 OAuth2 集成成熟。代价是过滤器链的调试成本高，一个配置错误常常表现为「403 但不知道为什么」。</p><h2>Sa-Token 的强项</h2><p>注解即鉴权，<code>@SaCheckLogin</code>、<code>@SaCheckPermission</code> 读起来就是意图。对中小项目更高效。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="Spring Security 与 Sa-Token 的取舍 · 示意图一" loading="lazy"><figcaption>Spring Security 与 Sa-Token 的取舍 · 示意图一</figcaption></figure><h2>判断依据</h2><p>需要对接标准协议（OIDC / SAML）选 Security；自建用户体系、追求开发效率选 Sa-Token。</p><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
