INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000033, 2230000000000000033, 1, '从单体到微服务：不该走的那一步', '拆服务的前提是团队与部署已经痛到必须拆。列出四个「其实还没到时候」的信号。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/a0d7253288d34e9492f52f9e88863b55.jpg', '<h2>四个还没到时候的信号</h2><ul><li>团队不到 10 人，沟通成本本来就低</li><li>没有自动化部署，拆完只会更痛</li><li>领域边界还没摸清，拆了就要不停改接口</li><li>单体性能瓶颈还没定位到具体模块</li></ul><h2>先做什么</h2><p>模块化单体：清晰的模块边界 + 单向依赖，等到某模块真的需要独立扩容时再拆，成本低一个数量级。</p><blockquote><p>微服务解决的是组织问题，不是性能问题。把它当性能方案，通常会失望。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/a0d7253288d34e9492f52f9e88863b55.jpg" alt="从单体到微服务：不该走的那一步 · 示意图一" loading="lazy"><figcaption>从单体到微服务：不该走的那一步 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/09/8e666e85dffe4c4dbe7b106c5170bfb6.jpg" alt="从单体到微服务：不该走的那一步 · 示意图二" loading="lazy"><figcaption>从单体到微服务：不该走的那一步 · 示意图二</figcaption></figure><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
