INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000034, 2230000000000000034, 1, '缓存一致性：先删缓存还是先更库', 'Cache Aside 的两种顺序都与「并发读写」有关。讲清延迟双删的适用条件与它的局限。', 'https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg', '<h2>两种顺序的问题</h2><p>先删缓存再更库：删除后、更新前的窗口里，读请求会把旧值重新写回缓存。先更库再删缓存：删除失败就长期不一致。</p><h2>延迟双删</h2><p>更新后延迟一小段时间再删一次，覆盖那个窗口。但延迟时长难定，且不解决删除失败。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg" alt="缓存一致性：先删缓存还是先更库 · 示意图一" loading="lazy"><figcaption>缓存一致性：先删缓存还是先更库 · 示意图一</figcaption></figure><h2>更可靠的思路</h2><p>缓存设过期时间做兜底 + 通过 binlog 订阅异步失效，把「一致性」降级为「最终一致」，这才是大多数业务的真实需求。</p><h2>如果重来一次，我会怎么改</h2><p>回头看，这件事本可以在半天内做完，实际花了两天。差别不在技术难度，而在动手前的十分钟：先写清楚验收标准，再写代码。</p><ul><li>先把"完成"定义成可验证的观测指标，而不是"功能跑通"</li><li>先做最小闭环（能跑通一条链路），再补齐异常分支</li><li>把回归手段前置：能一条命令复现的问题，改起来才敢下手</li></ul><p>顺序一换，很多"改到一半发现方向不对"的返工就不会发生。技术方案的价值，往往体现在它让后续每一次修改都更便宜。</p><blockquote><p>写代码的时间只占三分之一，剩下的是让它可被验证、可被回滚、可被接手。</p></blockquote><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p>', 1761000000000000103, 2210000000000000002, '2026-10-23 07:51:00', 2210000000000000002, '2026-10-23 07:51:00', '0');
