INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000035, 2230000000000000035, 1, '数据库连接池的常见误配', '池子不是越大越好。连接数超过数据库处理能力时，等待只是从应用层转移到了数据库层。', 'https://img.sdblog.us.ci/ruoyi/2026/10/08/c03f78e8acd9458894b03775ba998b5e.jpg', '<h2>一个够用的估算</h2><p>连接数 ≈ CPU 核数 × 2 + 磁盘数。四核机器上配 200 个连接，实际并行度仍然受 CPU 限制，多出来的连接只是在抢锁。</p><h2>三个必调参数</h2><ul><li>最大连接数</li><li>获取连接超时（不设会无限等）</li><li>空闲连接回收</li></ul><blockquote><p>池子配大了，故障时表现为「数据库 CPU 100% 但 QPS 很低」。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/08/c03f78e8acd9458894b03775ba998b5e.jpg" alt="数据库连接池的常见误配 · 示意图一" loading="lazy"><figcaption>数据库连接池的常见误配 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg" alt="数据库连接池的常见误配 · 示意图二" loading="lazy"><figcaption>数据库连接池的常见误配 · 示意图二</figcaption></figure><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
