INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000036, 2210000000000000002, NULL, '1', '0', 2240000000000000036, 2740, '2026-10-25 12:05:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000002, '2026-10-25 09:05:00', 2210000000000000002, '2026-10-25 09:05:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000036, 2230000000000000036, 1, '慢 SQL 治理的完整流程', '从开启慢日志到上线验证，六步闭环。附一条真实优化：从 2.3s 到 40ms。', 'https://img.sdblog.us.ci/ruoyi/2026/10/09/8e666e85dffe4c4dbe7b106c5170bfb6.jpg', '<h2>六步</h2><ul><li>开慢日志并定阈值</li><li>按总耗时排序（不是按单次耗时）</li><li>EXPLAIN 看执行计划</li><li>判断是索引问题还是查询结构问题</li><li>改写并回归</li><li>上线后对比</li></ul><h2>一个真实案例</h2><p>2.3s 的查询是「按时间范围 + 状态过滤 + 排序」，索引建在时间上但没带状态，导致回表量巨大。改成联合索引 <code>(status, created_at)</code> 后降到 40ms。</p><blockquote><p>慢 SQL 优化要先算「回表次数」，再决定加什么索引。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/09/8e666e85dffe4c4dbe7b106c5170bfb6.jpg" alt="慢 SQL 治理的完整流程 · 示意图一" loading="lazy"><figcaption>慢 SQL 治理的完整流程 · 示意图一</figcaption></figure></blockquote><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p>', 1761000000000000103, 2210000000000000002, '2026-10-25 09:05:00', 2210000000000000002, '2026-10-25 09:05:00', '0');
