INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000037, 2210000000000000003, NULL, '1', '0', 2240000000000000037, 2180, '2026-10-26 13:12:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000003, '2026-10-26 10:12:00', 2210000000000000003, '2026-10-26 10:12:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000037, 2230000000000000037, 1, '前端状态管理的边界', '不是所有状态都该进 store。区分服务端状态、UI 状态、表单状态，避免把缓存问题当状态问题。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg', '<h2>三类状态</h2><ul><li>服务端状态：应该由请求库管理（缓存、失效、重试）</li><li>UI 状态：弹层开关、选中项，放组件或轻量 store</li><li>表单状态：跟随表单库，不要全局化</li></ul><h2>最常见的问题</h2><p>把接口数据塞进全局 store 再手动维护失效，等于自己实现一遍请求库已经做好的事，还容易不一致。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg" alt="前端状态管理的边界 · 示意图一" loading="lazy"><figcaption>前端状态管理的边界 · 示意图一</figcaption></figure><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="前端状态管理的边界 · 示意图二" loading="lazy"><figcaption>前端状态管理的边界 · 示意图二</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
