INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000038, 2230000000000000038, 1, '组件库设计的三个取舍', '灵活性与一致性、受控与非受控、以及「要不要暴露 DOM」。每个取舍都影响后续所有使用者。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg', '<h2>灵活 vs 一致</h2><p>暴露太多 props 会让组件库失去统一观感，暴露太少则业务会 fork 一份自己改。折中是提供「受主题变量约束的有限扩展」。</p><h2>受控 vs 非受控</h2><p>受控便于外部联动，但每次都要写 v-model；非受控简单，却难做联动。多数组件应该两者都支持。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg" alt="组件库设计的三个取舍 · 示意图一" loading="lazy"><figcaption>组件库设计的三个取舍 · 示意图一</figcaption></figure><h2>要不要暴露 DOM</h2><p>暴露 ref 便于聚焦、滚动等操作，但也让使用者依赖内部结构。折中是暴露有限方法而不是元素本身。</p><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
