INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000039, 2210000000000000003, NULL, '1', '0', 2240000000000000039, 1880, '2026-10-28 15:26:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000003, '2026-10-28 12:26:00', 2210000000000000003, '2026-10-28 12:26:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000039, 2230000000000000039, 1, '无障碍不是可选项：WCAG 入门', '对比度、可访问名称、键盘可达、语义标签。四个最容易踩的点，配具体的反例。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/b8000d2667af49a28ed193eee931986a.jpg', '<h2>四个高频问题</h2><ul><li>对比度不足（正文要以 4.5:1 为线）</li><li>可访问名称与可见文字不一致（语音控制点不到）</li><li>自定义按钮没有键盘焦点</li><li>只用颜色区分状态</li></ul><h2>一个具体的反例</h2><p>按钮可见文字是「浅色」，但 <code>aria-label</code> 写的是「切换到深色」——语音用户说「点击浅色」永远点不到。</p><blockquote><p>无障碍的收益不只是少数用户。键盘可达、语义清晰，对所有人都是体验提升。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/b8000d2667af49a28ed193eee931986a.jpg" alt="无障碍不是可选项：WCAG 入门 · 示意图一" loading="lazy"><figcaption>无障碍不是可选项：WCAG 入门 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="无障碍不是可选项：WCAG 入门 · 示意图二" loading="lazy"><figcaption>无障碍不是可选项：WCAG 入门 · 示意图二</figcaption></figure><h2>如果重来一次，我会怎么改</h2><p>回头看，这件事本可以在半天内做完，实际花了两天。差别不在技术难度，而在动手前的十分钟：先写清楚验收标准，再写代码。</p><ul><li>先把"完成"定义成可验证的观测指标，而不是"功能跑通"</li><li>先做最小闭环（能跑通一条链路），再补齐异常分支</li><li>把回归手段前置：能一条命令复现的问题，改起来才敢下手</li></ul><p>顺序一换，很多"改到一半发现方向不对"的返工就不会发生。技术方案的价值，往往体现在它让后续每一次修改都更便宜。</p><blockquote><p>写代码的时间只占三分之一，剩下的是让它可被验证、可被回滚、可被接手。</p></blockquote><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p>', 1761000000000000103, 2210000000000000003, '2026-10-28 12:26:00', 2210000000000000003, '2026-10-28 12:26:00', '0');
