INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000040, 2230000000000000040, 1, '深色模式的实现陷阱', '不是加一个 .dark 类就完了。图片、阴影、边框、以及第三方组件的变量覆盖，四个地方最容易破。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg', '<h2>阴影在深色下几乎不可见</h2><p>深色背景上黑色阴影失效，通常改用「边框 + 略亮的底色」来表达层级。</p><h2>图片要压暗</h2><p>白底截图在深色页面上刺眼，加一层 <code>filter: brightness(.9)</code> 或降低不透明度会舒服很多。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="深色模式的实现陷阱 · 示意图一" loading="lazy"><figcaption>深色模式的实现陷阱 · 示意图一</figcaption></figure><h2>第三方组件</h2><p>富文本编辑器、图表库往往有自己的一套配色，必须逐个用变量覆盖，否则会出现「页面是深色、编辑器是白底」。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
