INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000042, 2230000000000000042, 1, '图片优化的正确姿势', '尺寸、格式、懒加载、占位。四条按收益排序，并解释为什么「先压到 100KB 以下」往往是错的。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg', '<h2>收益排序</h2><ul><li>按展示尺寸出图（通常能砍 80%）</li><li>换现代格式（WebP/AVIF，再砍 30~50%）</li><li>首屏外懒加载</li><li>固定宽高比占位防抖动</li></ul><h2>一个常见误区</h2><p>把 2000px 的图压到 100KB，视觉上糊了，但传输量仍然大于一张 400px 的清晰图。尺寸优先于压缩率。</p><blockquote><p>最有效的图片优化是「别传这么大的图」，而不是「想尽办法压小它」。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="图片优化的正确姿势 · 示意图一" loading="lazy"><figcaption>图片优化的正确姿势 · 示意图一</figcaption></figure></blockquote><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
