INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000044, 2230000000000000044, 1, 'HTTPS 握手都发生了什么', 'TLS 1.2 与 1.3 的握手对比、证书链校验、以及为什么 1.3 能省一个往返。', 'https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg', '<h2>TLS 1.2 的两个往返</h2><p>客户端问候 → 服务端问候 + 证书 → 客户端校验证书并生成密钥 → 双方切换加密。</p><h2>TLS 1.3 砍掉了什么</h2><p>把密钥交换提前到第一个往返，并移除了 RSA 密钥交换等不安全套件。首次连接省一个 RTT，会话恢复可以做到 0-RTT。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg" alt="HTTPS 握手都发生了什么 · 示意图一" loading="lazy"><figcaption>HTTPS 握手都发生了什么 · 示意图一</figcaption></figure><h2>证书链校验</h2><p>浏览器从站点证书往上追到受信任根，任何一环缺失或过期都会失败。中间证书忘配是线上最常见的握手失败原因。</p><h2>如果重来一次，我会怎么改</h2><p>回头看，这件事本可以在半天内做完，实际花了两天。差别不在技术难度，而在动手前的十分钟：先写清楚验收标准，再写代码。</p><ul><li>先把"完成"定义成可验证的观测指标，而不是"功能跑通"</li><li>先做最小闭环（能跑通一条链路），再补齐异常分支</li><li>把回归手段前置：能一条命令复现的问题，改起来才敢下手</li></ul><p>顺序一换，很多"改到一半发现方向不对"的返工就不会发生。技术方案的价值，往往体现在它让后续每一次修改都更便宜。</p><blockquote><p>写代码的时间只占三分之一，剩下的是让它可被验证、可被回滚、可被接手。</p></blockquote><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p>', 1761000000000000103, 2210000000000000004, '2026-10-30 09:01:00', 2210000000000000004, '2026-10-30 09:01:00', '0');
