INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000045, 2230000000000000045, 1, 'Linux 内存排查：free 为什么不准', 'buff/cache 不是「被占用」，available 才是判断依据。附三个真正需要警惕的信号。', 'https://img.sdblog.us.ci/ruoyi/2026/10/08/c03f78e8acd9458894b03775ba998b5e.jpg', '<h2>先看 available</h2><p><code>free</code> 的 <code>free</code> 列经常接近 0，那是内核把空闲内存拿去做缓存了，可回收。<code>available</code> 才是「新进程能用多少」。</p><h2>三个真信号</h2><ul><li>available 持续下降且不回升</li><li>swap 使用量持续增长</li><li>dmesg 里出现 OOM killer 记录</li></ul><blockquote><p>「内存不够」的判断标准是 OOM 或 swap 抖动，不是 free 列数字小。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/08/c03f78e8acd9458894b03775ba998b5e.jpg" alt="Linux 内存排查：free 为什么不准 · 示意图一" loading="lazy"><figcaption>Linux 内存排查：free 为什么不准 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg" alt="Linux 内存排查：free 为什么不准 · 示意图二" loading="lazy"><figcaption>Linux 内存排查：free 为什么不准 · 示意图二</figcaption></figure><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
