INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000046, 2230000000000000046, 1, 'systemd 与容器化进程管理', '容器里该不该用 systemd、PID 1 的信号处理、以及优雅停机的超时配置。', 'https://img.sdblog.us.ci/ruoyi/2026/10/09/8e666e85dffe4c4dbe7b106c5170bfb6.jpg', '<h2>容器不要跑 systemd</h2><p>容器的职责是跑一个前台进程。用 systemd 管多个服务会让信号转发、日志收集、健康检查全部变复杂，这些本该由编排层负责。</p><h2>PID 1 的信号</h2><p>如果应用不是 PID 1，SIGTERM 可能收不到。用 <code>exec</code> 形式启动，或加 <code>--init</code> 让 tini 转发信号。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/09/8e666e85dffe4c4dbe7b106c5170bfb6.jpg" alt="systemd 与容器化进程管理 · 示意图一" loading="lazy"><figcaption>systemd 与容器化进程管理 · 示意图一</figcaption></figure><pre><code class="language-bash"><span class="tok-21nrsd"># 正确：exec 让 java 成为 PID 1</span>
