INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000047, 2230000000000000047, 1, '灰度发布的几种实现', '按流量比例、按用户、按请求头。分别说明实现位置（网关 / 服务内 / 前端）与回滚代价。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg', '<h2>三种粒度</h2><ul><li>流量比例：网关按权重分流，实现简单，问题定位难</li><li>按用户：一致性哈希或白名单，体验稳定</li><li>按请求头：便于内部先验，需上游配合</li></ul><h2>回滚的关键</h2><p>新老版本要能同时读写同一份数据。若涉及表结构变更，必须先做「兼容双向」的迁移，否则回滚会丢数据。</p><blockquote><p>灰度的难点不在分流，在数据兼容。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/76bc03f6ec78479294db7e8aed5e16c9.jpg" alt="灰度发布的几种实现 · 示意图一" loading="lazy"><figcaption>灰度发布的几种实现 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="灰度发布的几种实现 · 示意图二" loading="lazy"><figcaption>灰度发布的几种实现 · 示意图二</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
