INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000048, 2210000000000000001, NULL, '1', '0', 2240000000000000048, 1450, '2026-10-31 16:29:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000001, '2026-10-31 13:29:00', 2210000000000000001, '2026-10-31 13:29:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000048, 2230000000000000048, 1, '监控告警：从指标到可执行', '告警要能指向动作。区分「需要人处理」与「只需记录」，避免告警疲劳。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg', '<h2>三类指标</h2><ul><li>黄金指标：延迟、流量、错误、饱和度</li><li>业务指标：下单量、支付成功率</li><li>资源指标：CPU、内存、磁盘</li></ul><h2>告警设计</h2><p>每条告警都要能回答「收到之后第一步做什么」。答不上来的，应该降级为看板而不是告警。</p><blockquote><p>告警疲劳的代价是真实的：当所有告警都被忽略，等于没有监控。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/89ace1ded77946f89b16e67857593822.jpg" alt="监控告警：从指标到可执行 · 示意图一" loading="lazy"><figcaption>监控告警：从指标到可执行 · 示意图一</figcaption></figure></blockquote><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
