INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000049, 2210000000000000001, NULL, '1', '0', 2240000000000000049, 2280, '2026-10-31 09:36:00', NULL, NULL, NULL, 1761000000000000103, 2210000000000000001, '2026-10-31 06:36:00', 2210000000000000001, '2026-10-31 06:36:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000049, 2230000000000000049, 1, '技术债的量化与偿还', '技术债不是道德问题。用「修改成本」与「故障概率」两个维度排序，把偿还排进迭代。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/b8000d2667af49a28ed193eee931986a.jpg', '<h2>两个维度</h2><ul><li>修改成本：每次改这块要多久、要动几个文件</li><li>故障概率：这块最近出过几次问题</li></ul><h2>四象限</h2><p>高成本 + 高故障：立刻还；高成本 + 低故障：排期还；低成本 + 高频：随手还；低成本 + 低频：记录即可。</p><blockquote><p>最糟的不是有技术债，是没人知道债在哪、有多贵。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/b8000d2667af49a28ed193eee931986a.jpg" alt="技术债的量化与偿还 · 示意图一" loading="lazy"><figcaption>技术债的量化与偿还 · 示意图一</figcaption></figure></blockquote><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="技术债的量化与偿还 · 示意图二" loading="lazy"><figcaption>技术债的量化与偿还 · 示意图二</figcaption></figure><h2>如果重来一次，我会怎么改</h2><p>回头看，这件事本可以在半天内做完，实际花了两天。差别不在技术难度，而在动手前的十分钟：先写清楚验收标准，再写代码。</p><ul><li>先把"完成"定义成可验证的观测指标，而不是"功能跑通"</li><li>先做最小闭环（能跑通一条链路），再补齐异常分支</li><li>把回归手段前置：能一条命令复现的问题，改起来才敢下手</li></ul><p>顺序一换，很多"改到一半发现方向不对"的返工就不会发生。技术方案的价值，往往体现在它让后续每一次修改都更便宜。</p><blockquote><p>写代码的时间只占三分之一，剩下的是让它可被验证、可被回滚、可被接手。</p></blockquote><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p>', 1761000000000000103, 2210000000000000001, '2026-10-31 06:36:00', 2210000000000000001, '2026-10-31 06:36:00', '0');
INSERT INTO sd_blog_article_tag (article_tag_id, article_id, tag_id, create_dept, create_by, create_time, update_by, update_time) VALUES (2260000000000000077, 2230000000000000049, 2220000000000000011, 1761000000000000103, 2210000000000000001, '2026-10-31 06:36:00', 2210000000000000001, '2026-10-31 06:36:00');
