INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000050, 2230000000000000050, 1, '写了三年博客之后', '一些与工具无关的体会：为什么写、写什么、以及如何避免写成「文档搬运」。', 'https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg', '<h2>为什么写</h2><p>写下来是检验「真的懂了」最便宜的方式。能讲清楚的部分才是自己的，剩下的会在写作过程中暴露。</p><h2>写什么</h2><p>只写自己踩过并解决了的。转述官方文档没有价值——读者可以直接读官方文档。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/27/6e30bd7413b3456b88c1a2ab73320ccd.jpg" alt="写了三年博客之后 · 示意图一" loading="lazy"><figcaption>写了三年博客之后 · 示意图一</figcaption></figure><h2>一个反模式</h2><p>开头先写一大段「什么是 X」的定义。读者点进来多半已经知道 X 是什么，他们想知道的是你遇到的问题。</p><blockquote><p>好文章的开头是一句具体的困扰，不是一句教科书定义。</p></blockquote><h2>一个小实验：先用最小代价验证假设</h2><p>遇到不确定的结论，我倾向于先写一个几十行的最小实验，而不是直接改生产代码。实验只要能证伪就够了，不需要优雅。</p><pre><code class="language-sql"><span class="tok-21nrsd">-- 验证"索引到底有没有被用上"：对比加索引前后的执行计划</span>
