INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000051, 2230000000000000051, 1, '（草稿）前端 monorepo 的构建缓存', '记录一个还没验证完的想法：用内容哈希做任务级缓存，避免整仓重建。', 'https://img.sdblog.us.ci/ruoyi/2026/09/30/1244374ebda34594ab6a220298f8c617.jpg', '<h2>待验证</h2><ul><li>输入指纹怎么算（源文件 + 依赖版本 + 环境变量）</li><li>输出目录怎么做失效判断</li><li>跨机器共享缓存的可信边界</li></ul><p><em>（草稿：还在试，先把思路记下来。）</em></p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/09/30/1244374ebda34594ab6a220298f8c617.jpg" alt="（草稿）前端 monorepo 的构建缓存 · 示意图一" loading="lazy"><figcaption>（草稿）前端 monorepo 的构建缓存 · 示意图一</figcaption></figure><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/06/bdabc344a78544f693b56459c04ede45.jpg" alt="（草稿）前端 monorepo 的构建缓存 · 示意图二" loading="lazy"><figcaption>（草稿）前端 monorepo 的构建缓存 · 示意图二</figcaption></figure><h2>边界条件比主流程更值得写</h2><p>文中这套做法在主流程上是成立的，但真正决定它能不能上线的，是几个不起眼的边界：数据量涨一个数量级之后复杂度怎么变、依赖服务抖一下会不会雪崩、以及出问题时能不能在十分钟内定位。</p><ul><li>数据规模：先用真实量级压测一遍，别拿几条样例数据下结论</li><li>失败路径：超时、重试、降级各跑一次，确认兜底不是"什么都不做"</li><li>可观测性：关键分支埋点或打日志，否则只能靠猜</li></ul><blockquote><p>能被复现的问题都不算难题，难的是"上次好好的，这次怎么就不行了"。</p></blockquote><p>所以我习惯在方案落地前先写一页"它会怎么坏"：列出三种最可能的失败方式，以及各自的观测手段。这一页往往比设计文档更早救火。</p><h2>和同类方案的取舍</h2><p>这类问题通常有三种解法：改代码、加中间层、换组件。三者不是先进与落后的关系，而是"把复杂度放在哪"的选择。</p><ul><li>改代码：成本最低、见效最快，但把复杂度留在了业务里，人一换就容易腐化</li><li>加中间层：隔离性好，代价是多一个要监控、要扩容、要背锅的东西</li><li>换组件：一次性收益大，迁移成本与团队熟悉度是隐性负债</li></ul><blockquote><p>架构决策没有正确答案，只有"此刻这个团队能维护得住"的答案。</p></blockquote><p>我这次选了第一种，因为团队只有三个人，多一个中间层意味着多一份值班负担；如果团队规模翻倍，我会重新评估第二种。</p>', 1761000000000000103, 2210000000000000003, '2026-10-27 09:00:00', 2210000000000000003, '2026-10-27 09:00:00', '0');
