INSERT INTO sd_blog_article (article_id, author_id, slug, status, visibility, current_version_id, view_count, published_at, admin_hidden_reason, admin_hidden_by, admin_hidden_time, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2230000000000000052, 2210000000000000004, NULL, '1', '2', 2240000000000000052, 980, '2026-10-29 12:57:00', '基准测试未注明运行环境与版本，结论不可复现，需补充实验条件后重新发布', 1761100000000000001, '2026-10-31 15:30:00', 1761000000000000103, 2210000000000000004, '2026-10-29 09:57:00', 2210000000000000004, '2026-10-29 09:57:00', '0');
INSERT INTO sd_blog_article_version (version_id, article_id, version_no, title, summary, cover_url, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2240000000000000052, 2230000000000000052, 1, '（已下线）一次误导性的性能对比', '文中基准测试的机器配置未注明，结论不可复现，已由管理员下线。', 'https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg', '<h2>原文结论（已作废）</h2><p>原文声称某框架比另一框架快 3 倍，但未注明并发数、数据规模与硬件配置，实测无法复现。</p><p>本文已被管理员下线。</p><figure><img src="https://img.sdblog.us.ci/ruoyi/2026/10/05/9ac5d3880f9742829bb6b2bb565ab7ed.jpg" alt="（已下线）一次误导性的性能对比 · 示意图一" loading="lazy"><figcaption>（已下线）一次误导性的性能对比 · 示意图一</figcaption></figure><h2>一次线上排查的记录</h2><p>线上出现的是"偶发变慢"，监控上表现为长尾抖动，平均值几乎没变。这类问题的第一原则是不要猜，先把时间花在能缩小范围的动作上。</p><pre><code class="language-bash"><span class="tok-21nrsd"># 1) 先确认是不是单机问题：对比各实例的 P99</span>
