INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000014, 2230000000000000016, 2210000000000000005, NULL, '看标题以为是水文，点进来发现是真踩过的，收藏。', 1761000000000000103, 2210000000000000005, '2026-09-06 19:45:00', 2210000000000000005, '2026-09-06 19:45:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000015, 2230000000000000017, 2210000000000000002, NULL, '「把个人偏好标成必须改是评审最常见的摩擦源」——这句值得贴在墙上。', 1761000000000000103, 2210000000000000002, '2026-09-12 01:52:00', 2210000000000000002, '2026-09-12 01:52:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000016, 2230000000000000018, 2210000000000000004, NULL, '之前一直以为这个问题只能靠加缓存解决，原来是索引的问题。', 1761000000000000103, 2210000000000000004, '2026-09-17 15:59:00', 2210000000000000004, '2026-09-17 15:59:00', '0');
INSERT INTO sd_blog_comment (comment_id, article_id, user_id, parent_id, content, create_dept, create_by, create_time, update_by, update_time, del_flag) VALUES (2250000000000000017, 2230000000000000019, 2210000000000000001, NULL, '这类文章最有价值的地方是给了判断依据，而不是给了一个标准答案。', 1761000000000000103, 2210000000000000001, '2026-09-22 05:06:00', 2210000000000000001, '2026-09-22 05:06:00', '0');
